import { useState, useEffect, useMemo } from "react";
import { Box, Typography, Select, MenuItem } from "@mui/material";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Cell,
  Tooltip as RechartTooltip,
  ResponsiveContainer,
} from "recharts";
import { SectionCard, SectionTitle } from "../../pages/HRPortal/styles";
import { FilterSelectWrapper } from "./styles";
import {
  ALL_DISEASES_BY_PERIOD,
  PERIOD_OPTIONS,
  formatDiseaseAmt,
  type DiseaseOption,
} from "./data";
import { useLocalization } from "@ui/ui-lib";

const DISEASE_FILTER_OPTIONS: DiseaseOption[] = [
  "All Diseases",
  "Orthopedic",
  "Cardiology",
  "General",
  "Dental",
  "Others",
];

export function DiseaseCategory() {
  const { localizationData } = useLocalization();
  const [diseaseFilter, setDiseaseFilter] =
    useState<DiseaseOption>("All Diseases");
  const [periodType, setPeriodType] = useState<"month" | "year">("month");
  const [selectedPeriod, setSelectedPeriod] = useState<string>(
    PERIOD_OPTIONS.month[0],
  );

  useEffect(() => {
    setSelectedPeriod(PERIOD_OPTIONS[periodType][0]);
  }, [periodType]);

  const _chartData = useMemo(() => {
    const entries = ALL_DISEASES_BY_PERIOD[periodType]?.[selectedPeriod] ?? [];
    if (diseaseFilter === "All Diseases") return entries;
    return entries.filter((e) => e.name === diseaseFilter);
  }, [diseaseFilter, periodType, selectedPeriod]);

  return (
    <SectionCard>
      <SectionTitle>Claims by Disease Category</SectionTitle>

      {/* Filters */}
      <Box sx={{ display: "flex", gap: 1.5, mb: 2, flexWrap: "wrap" }}>
        <FilterSelectWrapper>
          <Select
            size="small"
            value={diseaseFilter}
            onChange={(e) => setDiseaseFilter(e.target.value as DiseaseOption)}
            sx={{ fontSize: 12, height: 30, minWidth: 130 }}
          >
            {DISEASE_FILTER_OPTIONS.map((opt) => (
              <MenuItem key={opt} value={opt}>
                {opt}
              </MenuItem>
            ))}
          </Select>
        </FilterSelectWrapper>

        <FilterSelectWrapper>
          <Select
            size="small"
            value={periodType}
            onChange={(e) => setPeriodType(e.target.value as "month" | "year")}
            sx={{ fontSize: 12, height: 30, minWidth: 90 }}
          >
            <MenuItem value="month">Month</MenuItem>
            <MenuItem value="year">Year</MenuItem>
          </Select>
        </FilterSelectWrapper>

        <FilterSelectWrapper>
          <Select
            size="small"
            value={selectedPeriod}
            onChange={(e) => setSelectedPeriod(e.target.value)}
            sx={{ fontSize: 12, height: 30, minWidth: 110 }}
          >
            {PERIOD_OPTIONS[periodType].map((opt) => (
              <MenuItem key={opt} value={opt}>
                {opt}
              </MenuItem>
            ))}
          </Select>
        </FilterSelectWrapper>
      </Box>

      {/* Horizontal BarChart */}
      <ResponsiveContainer width="100%" height={200}>
        <BarChart
          data={_chartData}
          layout="vertical"
          margin={{ left: 8, right: 24 }}
        >
          <XAxis
            type="number"
            tickFormatter={(v: unknown) => formatDiseaseAmt(Number(v), localizationData?.data)}
            tick={{ fontSize: 11, fill: "#9ca3af" }}
            axisLine={false}
            tickLine={false}
          />
          <YAxis
            type="category"
            dataKey="name"
            tick={{ fontSize: 11, fill: "#374151" }}
            axisLine={false}
            tickLine={false}
            width={80}
          />
          <RechartTooltip
            contentStyle={{
              borderRadius: 8,
              border: "1px solid #e5e7eb",
              fontSize: 12,
            }}
            formatter={(v: unknown) => [formatDiseaseAmt(Number(v), localizationData?.data), "Amount"]}
          />
          <Bar dataKey="amount" radius={[0, 4, 4, 0]}>
            {_chartData.map((entry, i) => (
              <Cell key={i} fill={entry.color} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>

      {/* Legend dots */}
      <Box sx={{ display: "flex", gap: 2, mt: 1.5, flexWrap: "wrap" }}>
        {_chartData.map((d) => (
          <Box
            key={d.name}
            sx={{ display: "flex", alignItems: "center", gap: 0.5 }}
          >
            <Box
              sx={{
                width: 8,
                height: 8,
                borderRadius: "50%",
                backgroundColor: d.color,
              }}
            />
            <Typography sx={{ fontSize: 11, color: "#6b7280" }}>
              {d.name}
            </Typography>
          </Box>
        ))}
      </Box>
    </SectionCard>
  );
}

export default DiseaseCategory;
